590	// trimJSONSpace strips only the four JSON whitespace bytes (space, tab,
591	// carriage return, newline). bytes.TrimSpace would also remove U+000B and
592	// other Unicode whitespace, which is illegal around a JSON token and must
593	// therefore be rejected rather than ignored.
594	func trimJSONSpace(b []byte) []byte {
595		isSpace := func(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\n' }
596		for len(b) > 0 && isSpace(b[0]) {
597			b = b[1:]
598		}
599		for len(b) > 0 && isSpace(b[len(b)-1]) {
600			b = b[:len(b)-1]
601		}
602		return b
603	}
604	
605	// keyTokenBytes isolates one key token inside trimmed[start:end]. The
606	// decoder reports the offset just after the preceding token (so the span
607	// may still contain a separating comma and whitespace), hence the left trim.
608	func keyTokenBytes(trimmed []byte, start, end int) []byte {
609		return bytes.TrimLeft(trimmed[start:end], " \t\r\n,")
610	}
