701	// ParseManifest decodes data as a non-empty JSON array holding exactly the
702	// four required fields batch, product, quantity and unit per element. The
703	// three text fields must be JSON strings that are not blank after trimming;
704	// quantity must be a JSON integer (no strings, fractions or exponents) in
705	// the range 1..MaxQuantity. An empty file, empty array, non-array document
706	// or any malformed record is rejected. The manifest bytes are never written.
707	func ParseManifest(data []byte) ([]Input, error) {
708		trimmed := bytes.TrimSpace(data)
709		if len(trimmed) == 0 {
710			return nil, errors.New("manifest file is empty")
711		}
712		if trimmed[0] != '[' {
713			return nil, errors.New("manifest must be a non-empty JSON array of records")
714		}
715	
716		var elems []json.RawMessage
717		dec := json.NewDecoder(bytes.NewReader(data))
718		if err := dec.Decode(&elems); err != nil {
719			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
720		}
721		var extra json.RawMessage
722		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
723			if err == nil {
724				return nil, errors.New("manifest has unexpected data after the array")
725			}
726			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
727		}
728		if len(elems) == 0 {
729			return nil, errors.New("manifest must contain at least one record")
730		}
731	
732		inputs := make([]Input, 0, len(elems))
733		for i, raw := range elems {
734			pos := i + 1
735			in, err := parseManifestRecord(raw)
736			if err != nil {
737				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
738			}
739			inputs = append(inputs, in)
740		}
741		return inputs, nil
742	}
743	
744	// batchRecordFields are the only members a batch record may carry, in the
745	// registry file and in an import manifest alike.
746	var batchRecordFields = map[string]struct{}{
747		"batch": {}, "product": {}, "quantity": {}, "unit": {},
748	}
749	
750	// parseManifestRecord validates one manifest element: it must be a JSON
751	// object with exactly the four required keys, text fields as non-blank,
752	// valid UTF-8 strings and quantity as a strict JSON integer. The members
753	// are scanned with parseObjectFields (strict key decoding, duplicates kept
754	// visible) rather than a lenient map unmarshal, so malformed key or value
755	// bytes cannot be silently replaced with U+FFFD. Whatever makes the record
756	// fail — an unknown, duplicated or case-mismatched field included — the
757	// returned Input carries the normalized batch id whenever exactly one
758	// "batch" member holds valid, non-blank text, so the caller can name the
759	// batch in the error; otherwise it stays empty.
760	//
761	// The structural rules are shared with parseRegistryRecord; this source's
762	// own choices are: member-name anomalies are reported in source order
763	// (unknown and duplicate carry equal weight), text is trimmed and must stay
764	// non-empty, and reasons use manifest wording (including *EncodingError for
765	// malformed text). A member name that cannot be decoded fails the record
766	// with keyEncodingReason before the source-order anomaly scan — the
767	// U+FFFD-substituted text is never judged as an unknown or duplicate name.
768	func parseManifestRecord(raw json.RawMessage) (Input, error) {
769		var in Input
770		members, badKey, err := parseObjectFields(raw)
771		if err != nil {
772			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
773		}
774		// Attach the batch id to whatever error this record raises, but only when
775		// it is unambiguous: exactly one "batch" member (compared after JSON key
776		// decoding, so an escaped respelling counts as the same field) carrying a
777		// JSON string whose decoded text is valid UTF-8 and non-blank once
778		// trimmed. A missing, duplicated, mistyped, blank or malformed "batch"
779		// member leaves the id out — never a U+FFFD substitution, and never one
780		// of two duplicate values picked arbitrarily, even when both are equal.
781		// Where the "batch" member sits relative to the offending field does not
782		// matter.
783		in.Batch = unambiguousBatchID(members, textTrimmed)
784	
785		// A member name that cannot be decoded is a name-encoding problem, never
786		// an unknown field: the substituted text is not a real name.
787		if badKey {
788			return in, errors.New(keyEncodingReason)
789		}
790	
791		// Manifest member-name problems are reported in source order: the first
792		// unknown name or first repeat fails the record.
793		switch fault := checkRecordMembers(members, false); fault.kind {
794		case faultUnknown:
795			return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", fault.field)
796		case faultDuplicate:
797			return in, fmt.Errorf("record lists field %q more than once", fault.field)
798		}
799	
800		textField := func(name string) (string, error) {
801			rawValue, found := findField(members, name)
802			value, problem, cause := decodeRecordText(rawValue, found, textTrimmed)
803			switch problem {
804			case fieldMissing:
805				return "", fmt.Errorf("missing required field %q", name)
806			case fieldNotString:
807				return "", fmt.Errorf("field %q must be a JSON string", name)
808			case fieldEncoding:
809				return "", &EncodingError{Field: name}
810			case fieldBlank:
811				return "", fmt.Errorf("field %q must not be blank: %w", name, cause)
812			}
813			return value, nil
814		}
815	
816		in.Batch, err = textField("batch")
817		if err != nil {
818			return in, err
819		}
820		in.Product, err = textField("product")
821		if err != nil {
822			return in, err
823		}
824		in.Unit, err = textField("unit")
825		if err != nil {
826			return in, err
827		}
828		quantityRaw, ok := findField(members, "quantity")
829		if !ok {
830			return in, errors.New("missing required field \"quantity\"")
831		}
832		in.Quantity, err = manifestQuantityError(bytes.TrimSpace(quantityRaw))
833		if err != nil {
834			return in, err
835		}
836		return in, nil
837	}
838	
839	// ImportResult is one entry of an Import outcome: the normalized record in
840	// manifest order plus whether it was newly created or already present.
841	type ImportResult struct {
842		Batch   Batch
843		Created bool
844	}
845	
846	// validateManifestInput applies the same effective-value rules to one
847	// directly submitted record that Register enforces for single entries and
848	// parseManifestRecord enforces for file records: the three text fields must
849	// be valid UTF-8 and must not be empty strings, and quantity must lie in
850	// 1..MaxQuantity. Text is checked verbatim — direct submissions get no
851	// whitespace trimming or case folding (the command-line entry normalizes
852	// before constructing the Input), so whitespace-only text is accepted as
853	// ordinary non-empty text. pos is the record's 1-based position in this
854	// submission. The returned *ManifestRecordError names the offending field
855	// in its reason and cites the batch id only when that id is itself
856	// non-empty, valid UTF-8 text; it is never invented or substituted when the
857	// batch field is empty or malformed.
858	func validateManifestInput(in Input, pos int) error {
859		// batchID is "" whenever the batch field itself is empty or malformed, so
860		// it is safe to attach it to whichever error follows.
861		batchID := safeBatchIDForError(in.Batch)
862		// Import reports an encoding problem anywhere in the three text fields
863		// before any empty-text problem; quantity problems come after both.
864		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
865		if issue, bad := firstTextIssue(issues, textEncoding); bad {
866			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: (&EncodingError{Field: issue.field}).Error()}
867		}
868		if issue, bad := firstTextIssue(issues, textEmpty); bad {
869			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: fmt.Sprintf("field %q must not be empty", issue.field)}
870		}
871		switch classifyDecodedQuantity(in.Quantity) {
872		case decodedQtyNotPositive:
873			return &ManifestRecordError{Position: pos, Batch: batchID, Reason: `field "quantity" must be greater than zero`}
874		case decodedQtyAboveMax:
875			return &ManifestRecordError{Position: pos, Batch: batchID,
876				Reason: fmt.Sprintf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)}
877		}
878		return nil
879	}
880	
881	// Import validates every record of inputs before appending anything: the
882	// whole manifest fails if any record carries invalid UTF-8, an empty text
883	// field or a quantity outside 1..MaxQuantity — whether its batch id is new,
884	// already stored or seen earlier in this submission — or if any record
885	// conflicts with a stored record or with an earlier manifest record, and reg
886	// is left untouched on error. Directly submitted text is kept verbatim. New
887	// batch ids are appended in first-occurrence order; an id already stored or
888	// introduced earlier in the same manifest is confirmed as a duplicate only
889	// when product, quantity and unit all match. Results come back in manifest
890	// order; Created is false for duplicates.
891	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
892		if reg.Version != FormatVersion {
893			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
894		}
895		if len(inputs) == 0 {
896			return nil, errors.New("manifest must contain at least one record")
897		}
898		// Reject malformed text and non-effective values before touching
899		// anything; this covers records handed in directly by Go callers the
900		// same way ParseManifest covers file records, so a blank text field or a
901		// non-positive quantity can never reach the new/duplicate/conflict logic
902		// below and end up in a file the reader would refuse. Text is checked
903		// verbatim: direct submissions get no trimming or case folding (only the
904		// command-line entry normalizes, before building the Input).
905		for i, in := range inputs {
906			if err := validateManifestInput(in, i+1); err != nil {
907				return nil, err
908			}
909		}
910	
911		// Work on a copy: a rejected manifest must never partially land in reg.
912		working := append([]Batch(nil), reg.Batches...)
913		indexByID := make(map[string]int, len(working))
914		for i, b := range working {
915			indexByID[b.Batch] = i
916		}
917		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
918	
919		out := make([]ImportResult, len(inputs))
920		for i, in := range inputs {
921			pos := i + 1
922			if idx, known := indexByID[in.Batch]; known {
923				existing := working[idx]
924				diffs := diffFields(existing, in)
925				if len(diffs) > 0 {
926					if prev, inManifest := firstPos[in.Batch]; inManifest {
927						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
928					}
929					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
930				}
931				out[i] = ImportResult{Batch: existing, Created: false}
932				continue
933			}
934			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
935			working = append(working, b)
936			indexByID[in.Batch] = len(working) - 1
937			firstPos[in.Batch] = pos
938			out[i] = ImportResult{Batch: b, Created: true}
939		}
940	
941		reg.Batches = working
942		return out, nil
943	}
944	
945	// diffFields lists the members of product, quantity and unit in which in
946	// differs from existing, in that fixed order.
947	func diffFields(existing Batch, in Input) []string {
948		var diffs []string
949		if existing.Product != in.Product {
950			diffs = append(diffs, "product")
951		}
952		if existing.Quantity != in.Quantity {
953			diffs = append(diffs, "quantity")
954		}
955		if existing.Unit != in.Unit {
956			diffs = append(diffs, "unit")
957		}
958		return diffs
959	}
960	
961	// Register adds in to reg, or confirms the identical record already stored
962	// under the same batch id. A batch id held by a record differing in product,
963	// quantity or unit produces a *ConflictError and leaves reg untouched. The
964	// zero Outcome is returned together with the error.
965	func Register(reg *Registry, in Input) (Outcome, error) {
966		if reg.Version != FormatVersion {
967			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
968		}
969		// Register reports any empty text field before any encoding problem;
970		// quantity problems come after both.
971		issues := inspectRecordText(in.Batch, in.Product, in.Unit)
972		if _, bad := firstTextIssue(issues, textEmpty); bad {
973			return Outcome{}, errors.New("batch, product and unit must be non-empty")
974		}
975		if issue, bad := firstTextIssue(issues, textEncoding); bad {
976			return Outcome{}, &EncodingError{Field: issue.field}
977		}
978		if !quantityInRange(in.Quantity) {
979			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
980		}
981		for _, b := range reg.Batches {
982			if b.Batch != in.Batch {
983				continue
984			}
985			if diffs := diffFields(b, in); len(diffs) > 0 {
986				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
987			}
988			return Outcome{Batch: b, Created: false}, nil
989		}
990		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
991		reg.Batches = append(reg.Batches, b)
992		return Outcome{Batch: b, Created: true}, nil
993	}
994	
995	// validateForSave checks every record of reg against the rules Load enforces,
996	// so a hand-assembled registry cannot be persisted in a shape the reader
997	// would refuse. Records are checked in order and the first violation is
998	// reported as a *FormatError naming the 1-based record position, the field
999	// and the reason; the batch id is attached only when it is itself non-empty,
1000	// valid UTF-8 text — never a U+FFFD substitution for a malformed id. A batch
1001	// id seen twice is reported as a *DuplicateIDError carrying both 1-based
1002	// positions, even when the two records are identical: Save persists records,
1003	// it never confirms duplicates or merges them. Text is checked verbatim —
1004	// no trimming, no case folding — and reg is never modified.
1005	func validateForSave(reg *Registry) error {
1006		seen := make(map[string]int, len(reg.Batches))
1007		for i, b := range reg.Batches {
1008			pos := i + 1
1009			batchID := safeBatchIDForError(b.Batch)
1010			// Save reports the first problem in batch, product, unit field
1011			// order, with a field's encoding problem ahead of its empty-string
1012			// problem — exactly the order inspectRecordText lists issues in.
1013			if issues := inspectRecordText(b.Batch, b.Product, b.Unit); len(issues) > 0 {
1014				issue := issues[0]
1015				if issue.kind == textEncoding {
1016					return &FormatError{Position: pos, Batch: batchID, Field: issue.field,
1017						Reason: "must be valid UTF-8 text: malformed bytes are rejected instead of being replaced with U+FFFD"}
1018				}
1019				return &FormatError{Position: pos, Batch: batchID, Field: issue.field, Reason: "must not be empty"}
1020			}
1021			if !quantityInRange(b.Quantity) {
1022				return &FormatError{Position: pos, Batch: batchID, Field: "quantity",
1023					Reason: fmt.Sprintf("must be between 1 and %d", MaxQuantity)}
1024			}
1025			if first, dup := seen[b.Batch]; dup {
1026				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
1027			}
1028			seen[b.Batch] = pos
1029		}
1030		return nil
1031	}
1032	
1033	// WriteTempContent and RenameTempFile are the two failure-prone steps of the
1034	// atomic save — writing the new content into the temporary file, and replacing
1035	// the target with it — kept behind package-level variables so the regression
1036	// tests (including the batch-import entry-point tests in the cmd/govflow
1037	// package) can make a chosen step of a real save fail deterministically, on the
1038	// save's actual target rather than a neighboring unusable path. Production
1039	// behavior is exactly the wrapped os operations; production code never swaps
1040	// them.
1041	var (
1042		WriteTempContent = func(f *os.File, data []byte) (int, error) { return f.Write(data) }
1043		RenameTempFile   = os.Rename
1044	)
1045	
1046	// resolveRegistryTarget returns the file a save to path must actually
1047	// replace. When path is a symbolic link, the link is followed to its target
1048	// — an absolute target, or a relative one resolved against the link's own
1049	// directory, never against the process working directory — so the save
1050	// updates the file the user sees through the link instead of replacing the
1051	// link with a regular file. A dangling link or a link loop is an error: the
1052	// save must not create the target or overwrite the link as if this were a
1053	// first registration. A non-link path (existing or not) is returned
1054	// unchanged.
1055	func resolveRegistryTarget(path string) (string, error) {
1056		info, err := os.Lstat(path)
1057		if err != nil {
1058			if errors.Is(err, fs.ErrNotExist) {
1059				return path, nil
1060			}
1061			return "", fmt.Errorf("cannot inspect registry path: %w", err)
1062		}
1063		if info.Mode()&os.ModeSymlink == 0 {
1064			return path, nil
1065		}
1066		target, err := filepath.EvalSymlinks(path)
1067		if err != nil {
1068			return "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", err)
1069		}
1070		return target, nil
1071	}
1072	
1073	// Save atomically writes reg to path, replacing the file only after the new
1074	// content is fully on disk so an existing registry stays usable on failure.
1075	// Records are serialized in their current order; the file is created with
1076	// 0644 permissions or, when replacing an existing file, with its permissions.
1077	//
1078	// When path is a symbolic link, the link's target is the file replaced: the
1079	// new content is prepared next to the target and moved over it, so the link
1080	// stays a link to the same target and the target keeps its permissions,
1081	// while reads through either the link or the real path see the saved
1082	// records. A link whose target does not exist, or a link loop, rejects the
1083	// save with an error naming path — the target is never created and the link
1084	// is never replaced.
1085	//
1086	// Every record must satisfy the same effective-value rules Load enforces, so
1087	// a registry saved successfully always reads back: batch, product and unit
1088	// must be non-empty valid UTF-8 text (kept verbatim — no trimming or case
1089	// folding, so whitespace-only text is ordinary non-empty text), quantity
1090	// must lie in 1..MaxQuantity, and batch ids must be unique under exact
1091	// byte-for-byte comparison, two identical records included. Any violation
1092	// rejects the whole save before anything is written: an existing target
1093	// keeps its bytes and modification time, a missing target stays missing and
1094	// no temporary file is left behind. A nil or empty Batches is a legal empty
1095	// registry and is written as "batches": [] without touching reg itself.
1096	func Save(path string, reg *Registry) error {
1097		if reg.Version != FormatVersion {
1098			return fmt.Errorf("cannot write registry format version %d", reg.Version)
1099		}
1100		if err := validateForSave(reg); err != nil {
1101			return fmt.Errorf("cannot save registry %q: %w", path, err)
1102		}
1103		target, err := resolveRegistryTarget(path)
1104		if err != nil {
1105			return fmt.Errorf("cannot save registry %q: %w", path, err)
1106		}
1107		mode := os.FileMode(0o644)
1108		if info, err := os.Stat(target); err == nil {
1109			mode = info.Mode().Perm()
1110		} else if !errors.Is(err, fs.ErrNotExist) {
1111			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
1112		}
1113	
1114		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
1115			return fmt.Errorf("cannot save registry %q: %w", path, err)
1116		}
1117	
1118		// Encode a shallow copy so a nil Batches marshals as [] (null would not
1119		// read back) without mutating the caller's registry.
1120		out := *reg
1121		if out.Batches == nil {
1122			out.Batches = []Batch{}
1123		}
1124		var buf bytes.Buffer
1125		enc := json.NewEncoder(&buf)
1126		enc.SetEscapeHTML(false)
1127		enc.SetIndent("", "  ")
1128		if err := enc.Encode(&out); err != nil {
1129			return fmt.Errorf("cannot encode registry %q: %w", path, err)
1130		}
1131	
1132		tmp, err := os.CreateTemp(filepath.Dir(target), ".govflow-registry-*.tmp")
1133		if err != nil {
1134			return fmt.Errorf("cannot save registry %q: %w", path, err)
1135		}
1136		tmpName := tmp.Name()
1137		abort := func(cause error) error {
1138			tmp.Close()
1139			os.Remove(tmpName)
1140			return fmt.Errorf("cannot save registry %q: %w", path, cause)
1141		}
1142		if _, err := WriteTempContent(tmp, buf.Bytes()); err != nil {
1143			return abort(err)
1144		}
1145		if err := tmp.Chmod(mode); err != nil {
1146			return abort(err)
1147		}
1148		if err := tmp.Sync(); err != nil {
1149			return abort(err)
1150		}
1151		if err := tmp.Close(); err != nil {
1152			os.Remove(tmpName)
1153			return fmt.Errorf("cannot save registry %q: %w", path, err)
1154		}
1155		if err := RenameTempFile(tmpName, target); err != nil {
1156			os.Remove(tmpName)
1157			return fmt.Errorf("cannot save registry %q: %w", path, err)
1158		}
1159		return nil
1160	}
1161

