216		{Batch: "B-NEW-1", Product: "P-4", Quantity: 120, Unit: "box"},
217		{Batch: "B-NEW-2", Product: "新产品😀", Quantity: 3, Unit: "千克"},
218		{Batch: "B-NEW-3", Product: "P-9", Quantity: 1, Unit: "pallet"},
219	}
220	
221	// storedBatchesWhenMissing is the final registry order on success with no
222	// prior file: records land in manifest first-occurrence order.
223	var storedBatchesWhenMissing = []registerResult{
224		{Batch: "B-OLD-1", Product: "P-1", Quantity: 7, Unit: "kg"},
225		{Batch: "B-NEW-1", Product: "P-4", Quantity: 120, Unit: "box"},
226		{Batch: "B-OLD-2", Product: "苹果", Quantity: 80, Unit: "箱"},
227		{Batch: "B-NEW-2", Product: "新产品😀", Quantity: 3, Unit: "千克"},
228		{Batch: "B-NEW-3", Product: "P-9", Quantity: 1, Unit: "pallet"},
229	}
230	
231	// writeManifest serializes the shared rows as one JSON array file.
232	func writeManifest(t *testing.T, path string, rows []manifestRow) []byte {
233		t.Helper()
234		var buf bytes.Buffer
235		buf.WriteByte('[')
236		for i, r := range rows {
237			if i > 0 {
238				buf.WriteByte(',')
239			}
240			data, err := json.Marshal(r)
241			if err != nil {
242				t.Fatal(err)
243			}
244			buf.Write(data)
245		}
246		buf.WriteByte(']')
247		if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
248			t.Fatal(err)
249		}
250		return buf.Bytes()
251	}
252	
253	// runImportChild re-executes the test binary in wrapped one-command mode with
254	// the chosen fault and returns the child's exit code plus captured output.
255	// existingRegistry says whether the target file pre-exists, which decides
256	// which batch ids the fully prepared new table must contain.
257	func runImportChild(t *testing.T, registry, manifest string, fault saveFault, reason string, existingRegistry bool) (code int, stdout, stderr []byte) {
258		t.Helper()
259		exe, err := os.Executable()
260		if err != nil {
261			t.Fatal(err)
262		}
263		// Every manifest batch must be present in the prepared temporary file
264		// before the replacement is refused; B-OLD-3 additionally appears only
265		// when it was already stored.
266		markers := []string{
267			"B-OLD-1", "B-OLD-2", "B-NEW-1", "B-NEW-2", "B-NEW-3", "苹果", "新产品😀",
268		}
269		if existingRegistry {
270			markers = append(markers, "B-OLD-3")
271		}
272		cmd := exec.Command(exe, "-wrap.batch-import")
273		cmd.Env = append(os.Environ(),
274			"WRAP_REGISTRY="+registry,
275			"WRAP_INPUT="+manifest,
276			"WRAP_FAULT="+string(fault),
277			"WRAP_REASON="+reason,
278			"WRAP_MARKERS="+strings.Join(markers, ","),
279		)
280		var outBuf, errBuf bytes.Buffer
281		cmd.Stdout = &outBuf
282		cmd.Stderr = &errBuf
283		runErr := cmd.Run()
284		stdout = outBuf.Bytes()
285		stderr = errBuf.Bytes()
286		if runErr == nil {
287			return 0, stdout, stderr
288		}
289		var exitErr *exec.ExitError
290		if errors.As(runErr, &exitErr) {
291			return exitErr.ExitCode(), stdout, stderr
292		}
293		t.Fatalf("child process did not start: %v", runErr)
294		return 0, nil, nil
295	}
296	
297	// assertNoSaveLeftovers walks dir and fails if a save temporary file
298	// (".govflow-registry-*") or any file other than allowed survived.
299	func assertNoSaveLeftovers(t *testing.T, dir string, allowed ...string) {
300		t.Helper()
301		keep := map[string]bool{}
302		for _, name := range allowed {
303			keep[name] = true
304		}
305		err := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {
306			if err != nil || d.IsDir() {
307				return nil
308			}
309			if strings.HasPrefix(d.Name(), ".govflow-registry-") {
310				t.Errorf("failed import left a temporary registry file behind: %s", path)
311			}
312			if !keep[d.Name()] {
313				t.Errorf("failed import left an unexpected file behind: %s", path)
314			}
315			return nil
316		})
317		if err != nil {
318			t.Fatal(err)
319		}
320	}
321	
322	// TestBatchImportCLISaveFailuresAreAllOrNothing runs both injected save
323	// failures against both target states. The manifest is the shared legal one;
324	// the failure must be reported as a save failure and leave the world exactly
325	// as it was before the command.
326	func TestBatchImportCLISaveFailuresAreAllOrNothing(t *testing.T) {
327		causes := map[saveFault]string{
328			faultWrite:  "injected save failure: new registry content not fully written",
329			faultRename: "injected save failure: complete new registry cannot replace the target",
330		}
331		for _, fault := range []saveFault{faultWrite, faultRename} {
332			for _, target := range []string{"existing registry", "missing registry"} {
333				name := string(fault) + "/" + strings.ReplaceAll(target, " ", "_")
334				t.Run(name, func(t *testing.T) {
335					dir := t.TempDir()
336					registry := filepath.Join(dir, "reg.json")
337					manifest := filepath.Join(dir, "arrivals.json")
338					existing := target == "existing registry"
339					var originalBytes []byte
340					if existing {
341						writeFile(t, registry, importFailureRegistryJSON)
342						if err := os.Chtimes(registry, importFailurePinnedModTime, importFailurePinnedModTime); err != nil {
343							t.Fatal(err)
344						}
345						originalBytes = readFileSnapshot(t, registry)
346					}
347					manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
348	
349					code, stdout, stderr := runImportChild(t, registry, manifest, fault, causes[fault], existing)
350	
351					// The caller must observe a command failure, not a success.
352					if code != 1 {
353						t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
354					}
355					if len(bytes.TrimSpace(stdout)) != 0 {
356						t.Fatalf("stdout must stay empty on save failure, got %q", stdout)
357					}
358					msg := string(stderr)
359					// stderr must identify the command, the target registry path
360					// and the concrete save reason.
361					for _, want := range []string{
362						"govflow: batch-import:",
363						"cannot save registry",
364						registry,
365						causes[fault],
366					} {
367						if !strings.Contains(msg, want) {
368							t.Fatalf("stderr must contain %q:\n%s", want, msg)
369						}
370					}
371					// The manifest is legal and conflict-free (proven by the
372					// success controls below); the failure wording must never
373					// masquerade as invalid input or a batch conflict.
374					for _, mustNot := range []string{"invalid input", "conflicts with"} {
375						if strings.Contains(msg, mustNot) {
376							t.Fatalf("a save failure must not be reported as %q:\n%s", mustNot, msg)
377						}
378					}
379	
380					if existing {
381						// The existing registry survives with exact bytes and
382						// modification time and still loads with its original
383						// records, fields and order.
384						info, err := os.Stat(registry)
385						if err != nil {
386							t.Fatalf("the original registry must still exist: %v", err)
387						}
388						if !info.ModTime().Equal(importFailurePinnedModTime) {
389							t.Fatalf("failed import changed the registry mtime: got %v, want %v",
390								info.ModTime(), importFailurePinnedModTime)
391						}
392						after := readFileSnapshot(t, registry)
393						if !bytes.Equal(after, originalBytes) {
394							t.Fatalf("failed import changed the registry bytes:\nbefore: %s\nafter:  %s", originalBytes, after)
395						}
396						if bytes.Contains(after, []byte("B-NEW-")) {
397							t.Fatalf("part of the manifest landed in the registry: %s", after)
398						}
399						stored := readStoredBatches(t, registry)
400						wantStored := []registerResult{
401							{Batch: "B-OLD-1", Product: "P-1", Quantity: 7, Unit: "kg"},
402							{Batch: "B-OLD-2", Product: "苹果", Quantity: 80, Unit: "箱"},
403							{Batch: "B-OLD-3", Product: "P-3", Quantity: 9223372036854775807, Unit: "m"},
404						}
405						if len(stored) != len(wantStored) {
406							t.Fatalf("registry must keep exactly its original batches, got %+v", stored)
407						}
408						for i, want := range wantStored {
409							got := stored[i]
410							got.Status = ""
411							if got != want {
412								t.Fatalf("original record %d = %+v, want %+v", i+1, got, want)
413							}
414						}
415					} else {
416						// With no prior registry there must still be no file: not
417						// an empty registry, not the first few manifest rows.
418						if _, err := os.Stat(registry); !os.IsNotExist(err) {
419							t.Fatalf("failed import must not create the registry, stat err=%v", err)
420						}
421					}
422					assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
423					assertFileUnchanged(t, manifest, manifestBytes)
424				})
425			}
426		}
427	}
428	
429	// decodeImportEnvelope parses stdout strictly as one JSON object carrying
430	// exactly one member, "results", whose elements are generic objects for
431	// per-key assertions.
432	func decodeImportEnvelope(t *testing.T, raw []byte) []map[string]any {
433		t.Helper()
434		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
435		var envelope map[string]json.RawMessage
436		if err := dec.Decode(&envelope); err != nil {
437			t.Fatalf("stdout is not a JSON object: %v (%q)", err, raw)
438		}
439		if err := dec.Decode(&struct{}{}); err != io.EOF {
440			t.Fatalf("stdout must hold exactly one JSON object, got %q", raw)
441		}
442		if len(envelope) != 1 {
443			t.Fatalf("result object must carry exactly \"results\", got keys %v from %q", envelope, raw)
444		}
445		resultsRaw, ok := envelope["results"]
446		if !ok {
447			t.Fatalf("result object is missing \"results\": %q", raw)
448		}
449		var rows []map[string]any
450		if err := json.Unmarshal(resultsRaw, &rows); err != nil {
451			t.Fatalf("results is not an array of objects: %v (%s)", err, resultsRaw)
452		}
453		return rows
454	}
455	
456	// assertImportResults checks every result entry against its manifest-order
457	// expectation: exactly the five public keys, normalized four fields and the
458	// created/duplicate status.
459	func assertImportResults(t *testing.T, stdout []byte, want []expectedImportRow) {
460		t.Helper()
461		rows := decodeImportEnvelope(t, stdout)
462		if len(rows) != len(want) {
463			t.Fatalf("got %d results, want %d (manifest order): %s", len(rows), len(want), stdout)
464		}
465		for i, w := range want {
466			got := rows[i]
467			if len(got) != 5 {
468				t.Fatalf("result %d carries %d keys, want exactly 5: %v", i+1, len(got), got)
469			}
470			for _, key := range []string{"batch", "product", "quantity", "unit", "status"} {
471				if _, ok := got[key]; !ok {
472					t.Fatalf("result %d is missing key %q: %v", i+1, key, got)
473				}
474			}
475			if got["batch"] != w.batch || got["product"] != w.product || got["unit"] != w.unit {
476				t.Errorf("result %d text fields = %q/%q/%q, want %q/%q/%q",
477					i+1, got["batch"], got["product"], got["unit"], w.batch, w.product, w.unit)
478			}
479			quantity, ok := got["quantity"].(float64)
480			if !ok || int64(quantity) != w.quantity {
481				t.Errorf("result %d quantity = %v, want %d", i+1, got["quantity"], w.quantity)
482			}
483			if got["status"] != w.status {
484				t.Errorf("result %d status = %v, want %q", i+1, got["status"], w.status)
485			}
486		}
487	}
488	
489	// assertResultsMatchRegistry cross-checks every result entry against the
490	// record with the same batch id in the final registry, so completion is
491	// established by field-level content agreement rather than result count.
492	func assertResultsMatchRegistry(t *testing.T, want []expectedImportRow, stored []registerResult) {
493		t.Helper()
494		byID := make(map[string]registerResult, len(stored))
495		for _, b := range stored {
496			byID[b.Batch] = b
497		}
498		for i, r := range want {
499			s, ok := byID[r.batch]
500			if !ok {
501				t.Fatalf("result %d names batch %q which is absent from the final registry", i+1, r.batch)
502			}
503			if s.Product != r.product || s.Quantity != r.quantity || s.Unit != r.unit {
504				t.Fatalf("result %d (%+v) disagrees with the stored record %+v", i+1, r, s)
505			}
506		}
507	}
508	
509	// assertStoredBatches compares the registry's records in file order.
510	func assertStoredBatches(t *testing.T, registry string, want []registerResult) {
511		t.Helper()
512		stored := readStoredBatches(t, registry)
513		if len(stored) != len(want) {
514			t.Fatalf("registry holds %d records, want %d: %+v", len(stored), len(want), stored)
515		}
516		for i, w := range want {
517			got := stored[i]
518			got.Status = ""
519			if got != w {
520				t.Errorf("stored record %d = %+v, want %+v", i+1, got, w)
521			}
522		}
523	}
524	
525	// The success control against an existing registry: with the save healthy the
526	// very manifest that failed above imports. Results arrive in manifest order
527	// with the right statuses and normalized fields, the old records keep their
528	// order and the new batches append in first-occurrence order, and every result
529	// agrees field by field with the final registry.
530	func TestBatchImportCLISaveSuccessAgainstExistingRegistry(t *testing.T) {
531		dir := t.TempDir()
532		registry := filepath.Join(dir, "reg.json")
533		manifest := filepath.Join(dir, "arrivals.json")
534		writeFile(t, registry, importFailureRegistryJSON)
535		if err := os.Chtimes(registry, importFailurePinnedModTime, importFailurePinnedModTime); err != nil {
536			t.Fatal(err)
537		}
538		manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
539	
540		var stdout bytes.Buffer
541		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
542			t.Fatalf("the legal manifest must import when the save does not fail: %v", err)
543		}
544	
545		// A real save must have happened (new batches exist), observable as a new
546		// mtime rather than the pinned one.
547		info, err := os.Stat(registry)
548		if err != nil {
549			t.Fatal(err)
550		}
551		if info.ModTime().Equal(importFailurePinnedModTime) {
552			t.Fatal("a creating import must replace the file; the pinned mtime survived")
553		}
554	
555		assertImportResults(t, stdout.Bytes(), manifestResultsAgainstExisting)
556		stored := readStoredBatches(t, registry)
557		assertStoredBatches(t, registry, storedBatchesAfterExisting)
558		assertResultsMatchRegistry(t, manifestResultsAgainstExisting, stored)
559		assertFileUnchanged(t, manifest, manifestBytes)
560		assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
561	}
562	
563	// The success control with no prior registry: the file is created, the
564	// formerly-stored batches of the shared manifest are now created too, the
565	// within-manifest repeat is the only duplicate, and results again match the
566	// created file field by field.
567	func TestBatchImportCLISaveSuccessWithMissingRegistry(t *testing.T) {
568		dir := t.TempDir()
569		registry := filepath.Join(dir, "reg.json")
570		manifest := filepath.Join(dir, "arrivals.json")
571		manifestBytes := writeManifest(t, manifest, importFailureManifestRows)
572	
573		var stdout bytes.Buffer
574		if err := runBatchImport([]string{"--registry", registry, "--input", manifest}, &stdout); err != nil {
575			t.Fatalf("the legal manifest must import and create the registry: %v", err)
576		}
577	
578		assertImportResults(t, stdout.Bytes(), manifestResultsWhenMissing)
579		stored := readStoredBatches(t, registry)
580		assertStoredBatches(t, registry, storedBatchesWhenMissing)
581		assertResultsMatchRegistry(t, manifestResultsWhenMissing, stored)
582		assertFileUnchanged(t, manifest, manifestBytes)
583		assertNoSaveLeftovers(t, dir, filepath.Base(manifest), filepath.Base(registry))
584	}
585	
586	// The save-failure path must surface the quoted target path verbatim; this
587	// guards the wording the failure scenarios assert on, in a direct check that
588	// reads naturally when it breaks.
589	func TestBatchImportCLISaveFailureWordingNamesPath(t *testing.T) {
590		dir := t.TempDir()
591		registry := filepath.Join(dir, "reg.json")
592		manifest := filepath.Join(dir, "arrivals.json")
593		writeFile(t, registry, importFailureRegistryJSON)
594		writeManifest(t, manifest, importFailureManifestRows)
595	
596		code, stdout, stderr := runImportChild(t, registry, manifest, faultRename, "injected replacement refusal", true)
597		if code != 1 {
598			t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
599		}
600		if len(stdout) != 0 {
601			t.Fatalf("stdout must be empty, got %q", stdout)
602		}
603		want := "cannot save registry " + strconv.Quote(registry) + ": injected replacement refusal"
604		if !strings.Contains(string(stderr), want) {
605			t.Fatalf("stderr must contain %q:\n%s", want, stderr)
606		}
607	}
